'use client';

import { useEffect, useRef } from 'react';

type PaintBlob = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  angle: number;
  age: number;
  maxAge: number;
};

export default function HeroAnimation() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const lastPointRef = useRef<{ x: number; y: number } | null>(null);
  const blobsRef = useRef<PaintBlob[]>([]);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const parent = canvas?.parentElement;
    if (!canvas || !parent) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resizeCanvas = () => {
      const rect = parent.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const drawBlob = (blob: PaintBlob) => {
      const alpha = Math.pow(Math.max(0, 1 - blob.age / blob.maxAge), 1.5) * 0.9;
      const rx = blob.size;
      const ry = rx * 0.52;
      const wobble = Math.sin(blob.age * 0.04) * 0.06;
      const rotation = blob.angle + wobble;

      const gradient = ctx.createRadialGradient(blob.x, blob.y, 0, blob.x, blob.y, rx);
      gradient.addColorStop(0, `rgba(255, 255, 255, ${alpha})`);
      gradient.addColorStop(0.5, `rgba(255, 255, 255, ${alpha * 0.75})`);
      gradient.addColorStop(0.82, `rgba(255, 255, 255, ${alpha * 0.3})`);
      gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

      ctx.save();
      ctx.translate(blob.x, blob.y);
      ctx.rotate(rotation);
      ctx.beginPath();
      ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
      ctx.fillStyle = gradient;
      ctx.fill();
      ctx.restore();
    };

    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const nextBlobs = blobsRef.current.filter((blob) => blob.age <= blob.maxAge);
      blobsRef.current = nextBlobs;

      for (const blob of nextBlobs) {
        blob.age += 1;
        blob.x += blob.vx;
        blob.y += blob.vy;
        blob.vy += 0.012;
        blob.vx *= 0.995;
        drawBlob(blob);
      }

      rafRef.current = window.requestAnimationFrame(render);
    };

    const spawnBlob = (x: number, y: number, direction: number) => {
      const size = 14 + Math.random() * 22;
      const maxAge = 110 + Math.random() * 90;
      const angle = direction + (Math.random() * 1.2 - 0.6);

      blobsRef.current.push({
        x,
        y,
        vx: (Math.random() - 0.5) * 1.2,
        vy: Math.random() * 0.25,
        size,
        angle,
        age: 0,
        maxAge,
      });

      if (Math.random() < 0.45) {
        const normal = direction + Math.PI / 2;
        const offset = (Math.random() - 0.5) * 52;
        const satelliteSize = 3 + Math.random() * 9;

        blobsRef.current.push({
          x: x + Math.cos(normal) * offset,
          y: y + Math.sin(normal) * offset,
          vx: (Math.random() - 0.5) * 2.2,
          vy: 0.2 + Math.random() * 0.8,
          size: satelliteSize,
          angle: direction + (Math.random() * 1.2 - 0.6),
          age: 0,
          maxAge: 70 + Math.random() * 60,
        });
      }
    };

    const handlePointerMove = (event: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;

      if (x < 0 || y < 0 || x > rect.width || y > rect.height) {
        lastPointRef.current = null;
        return;
      }

      const previousPoint = lastPointRef.current;
      if (previousPoint) {
        const dx = x - previousPoint.x;
        const dy = y - previousPoint.y;
        const distance = Math.hypot(dx, dy);

        if (distance > 0) {
          const direction = Math.atan2(dy, dx);
          const steps = Math.max(1, Math.ceil(distance / 4));

          for (let index = 1; index <= steps; index += 1) {
            const t = index / steps;
            const pointX = previousPoint.x + dx * t;
            const pointY = previousPoint.y + dy * t;
            spawnBlob(pointX, pointY, direction);
          }
        }
      }

      lastPointRef.current = { x, y };
    };

    const handlePointerLeave = () => {
      lastPointRef.current = null;
    };

    resizeCanvas();
    render();

    window.addEventListener('mousemove', handlePointerMove);
    window.addEventListener('resize', resizeCanvas);
    parent.addEventListener('mouseleave', handlePointerLeave);

    return () => {
      if (rafRef.current) {
        window.cancelAnimationFrame(rafRef.current);
      }
      window.removeEventListener('mousemove', handlePointerMove);
      window.removeEventListener('resize', resizeCanvas);
      parent.removeEventListener('mouseleave', handlePointerLeave);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 h-full w-full"
      style={{ mixBlendMode: 'difference' }}
    />
  );
}
